function cdqV19OpenOfflineSheet(id){
  const url='https://docs.google.com/spreadsheets/d/'+encodeURIComponent(String(id||''))+'/edit';
  const href=/Android/i.test(navigator.userAgent||'')
    ? 'intent://docs.google.com/spreadsheets/d/'+encodeURIComponent(String(id||''))+'/edit#Intent;scheme=https;package=com.google.android.apps.docs.editors.sheets;S.browser_fallback_url='+encodeURIComponent(url)+';end'
    : url;
  const a=document.createElement('a');
  a.href=href;
  a.target='_blank';
  a.rel='noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  if(String(utilisateurCourantRole||'')!=='lecture'){
    fichierOuvertPourModification=id;
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',(cdqDocumentMeta(id)||{}).dateModification||'');
    sessionStorage.setItem('momentModification',String(Date.now()));
  }
  return true;
}
